import {occupationEssentials} from './occupation-essentials.js?v=0.31.0';
import {escapeHTML as h} from './html.js?v=0.31.0';
const contextIds={schedule:'4.C.3.d.4',team:'4.C.1.b.1.e',pressure:'4.C.3.d.1',contact:'4.C.1.a.4',standing:'4.C.2.d.1.b'};
// Unsuppressed categories are lower bounds, never renormalized into a full distribution.
export function contextShare(o,key,categories){const item=o?.context?.items?.find(x=>x.id===contextIds[key]);if(!item)return null;return {percent:item.responses.filter(r=>categories.includes(Number(r.category))).reduce((n,r)=>n+r.percent,0),source:o.url,date:item.referenceDate,sample:item.sampleSize,complete:item.distributionStatus==='complete_categories'};}
export const qualitativeContext={
 'financial-analysis':{facts:['Most work is office-based and full time.','Some jobs involve more than 40 hours or travel to clients.'],sourceURL:'https://www.bls.gov/ooh/business-and-financial/financial-analysts.htm'},
 emt:{facts:['Emergency response depends on a team.','Nights, weekends, holidays, and extended shifts can be part of the schedule.','Patient lifting and infection precautions are part of the work.'],sourceURL:'https://www.bls.gov/ooh/healthcare/emts-and-paramedics.htm'},
 tattoo:{facts:['Work directly with clients in a licensed studio.','Sanitation, protective equipment, and client records are essential duties.'],sourceURL:'https://www.dshs.texas.gov/tattoo-body-piercing-studios/licensing-requirements-tattoo-body-piercing-studios'}
};
export function careerActivityFeedback(s,id){const rows=(s.actions||[]).filter(a=>a.careerId===id&&a.done&&['more','less','curious'].includes(a.interestFeedback));return {rows,more:rows.filter(a=>a.interestFeedback==='more').length,less:rows.filter(a=>a.interestFeedback==='less').length,curious:rows.filter(a=>a.interestFeedback==='curious').length};}
export function careerInsights(s,o){
 if(!o)return {connections:[],tradeoffs:[],next:[]};const a=s.profileJourney?.answers||{},e=occupationEssentials[o.soc],team=contextShare(o,'team',[4,5]),regular=contextShare(o,'schedule',[1]),irregular=contextShare(o,'schedule',[2,3]),pressure=contextShare(o,'pressure',[4,5]),contact=contextShare(o,'contact',[4,5]);const connections=[],tradeoffs=[],next=[],sources=new Set();const add=(where,text,fact)=>{where.push(text);if(fact?.source)sources.add(fact.source);};
 if(team?.percent>=60){if(a.company==='independent')add(tradeoffs,'Teamwork is a big part of this job. Try a shared project before deciding.',team);else if(a.company==='team'||a.company==='mix')add(connections,'You enjoy working with others. Teamwork matters in this job.',team);}
 if(regular?.percent>=60&&a.rhythm==='routine')add(connections,'This job often has a regular schedule. You said you like a routine.',regular);
 if(irregular?.percent>=60&&a.rhythm==='routine')add(tradeoffs,'Schedules can change. Compare that with the steady routine you want.',irregular);
 if(contact?.percent>=60&&a.company==='independent')add(tradeoffs,'This job involves lots of contact with people. You said you prefer working alone.',contact);
 if(pressure?.percent>=60)add(next,'Ask how the team handles busy days and deadlines.',pressure);
 if((a.education||[]).includes('training')&&!(a.education||[]).some(x=>['college','graduate','unknown'].includes(x))&&['bachelor','graduate'].includes(o.finance?.credentialLevel))tradeoffs.push('This job usually needs a degree. You chose a shorter training route.');
 if(o.finance?.credentialLevel==='graduate'&&Array.isArray(a.education)&&!a.education.some(x=>['graduate','unknown'].includes(x)))tradeoffs.push('This job needs more study after college. Plan for the extra time and cost.');
 const reflection={curiosity:'You want to keep learning. Try an introductory lesson in '+(e?.knowledge?.[0]?.name?.toLowerCase()||'this subject')+'.',creativity:'You value original work. Ask where people can propose ideas and improve the way this job is done.',impact:'You want your work to matter. Ask who benefits from a typical day’s work.',independence:'You value independence. Ask which decisions a new employee makes and which need supervision.',community:'You value connection. Meet a team and notice how people support one another.',stability:'You value security. Compare paid hours, benefits, and whether the job is employed or self-employed.',variety:'You enjoy variety. Ask how a normal week differs from the most exciting example.',mastery:'You want to build skills. Pick one skill to practise and get feedback on.'};
 for(const id of s.priorities||[])if(reflection[id])next.push(reflection[id]);
 const qualitative=qualitativeContext[o.id];if(qualitative){sources.add(qualitative.sourceURL);for(const text of qualitative.facts)next.push(text);if(o.id==='emt'&&a.company==='independent')tradeoffs.push('You prefer independent work. Emergency response relies on a team.');if(o.id==='emt'&&a.rhythm==='routine')tradeoffs.push('You prefer a steady routine. Emergency shifts can include nights, weekends, and holidays.');}
 const feedback=careerActivityFeedback(s,o.id);if(feedback.more)connections.unshift('You tried '+feedback.more+' '+(feedback.more===1?'activity':'activities')+' and wanted to explore more.');if(feedback.less)tradeoffs.unshift('After trying the work, you felt less interested. Keep this option open only if you want another experience.');if(feedback.curious)next.unshift('You are still curious after trying the work. Choose a different task for your next experiment.');
 return {connections:[...new Set(connections)],tradeoffs:[...new Set(tradeoffs)],next:[...new Set(next)],feedback,sources:[...sources]};
}
export function careerInsightsPanel(s,o,{compact=false}={}){const r=careerInsights(s,o);if(!r.connections.length&&!r.tradeoffs.length&&(compact||!r.next.length))return '';return `<section class="career-insights ${compact?'compact':''}"><h3>${compact?'How you like to work':'How you like to work'}</h3>${r.connections.slice(0,1).map(t=>`<p class="insight-positive"><span aria-hidden="true">✓</span> ${h(t)}</p>`).join('')}${r.tradeoffs.slice(0,1).map(t=>`<p class="insight-tradeoff"><span aria-hidden="true">↔</span> ${h(t)}</p>`).join('')}${!compact&&(r.next.length||r.connections.length>1||r.tradeoffs.length>1)?'<details class="more-info"><summary>More info · work preferences</summary>'+[...r.connections.slice(1),...r.tradeoffs.slice(1),...r.next.slice(0,3)].map(t=>'<p>'+h(t)+'</p>').join('')+(r.sources.length?'<p>'+r.sources.map(u=>'<a href="'+h(u)+'" target="_blank" rel="noopener">Work setting source ↗</a>').join(' · ')+'</p>':'')+'</details>':''}</section>`;}
